mapper.select:
SELECT G.PTL_GRP_CD AS ptlGrpCd, GD.PTL_GRP_NM AS ptlGrpNm, G.POLLING_INTVAL AS pollingIntval, G.TIMEOUT_MS AS timeoutMs, G.RETRY_CNT AS retryCnt, G.SORT_ORD AS sortOrd, G.FRAME_RULE AS frameRule, G.CMD_GAP_MS AS cmdGapMs, G.INIT_ROUTINE AS initRoutine, G.INIT_DELAY_MS AS initDelayMs FROM ju_protocol_group G LEFT JOIN ju_protocol_group_detail GD ON GD.PTL_GRP_CD = G.PTL_GRP_CD WHERE G.USE_YN = 'YENO0001'
AND G.PTL_GRP_CD = #{ptlGrpCd}
ORDER BY G.SORT_ORD, G.PTL_GRP_CD

SELECT P.PTL_GRP_CD AS ptlGrpCd, P.PTL_CD AS ptlCd, P.PTL_TYPE AS ptlType, P.PTL_LEN AS ptlLen, P.PTL_VAL AS ptlVal, PD.PTL_NM AS ptlNm, PD.PTL_DESC AS ptlDesc, P.PTL_ROLES AS ptlRoles, P.PTL_ACTION AS ptlAction, P.EXPECT_RULE AS expectRule, P.IDEMPOTENT_YN AS idempotentYn FROM ju_protocol P JOIN ju_protocol_group G ON G.PTL_GRP_CD = P.PTL_GRP_CD AND G.USE_YN = 'YENO0001' LEFT JOIN ju_protocol_detail PD ON PD.PTL_GRP_CD = P.PTL_GRP_CD AND PD.PTL_CD = P.PTL_CD WHERE P.USE_YN = 'YENO0001'
AND P.PTL_GRP_CD = #{ptlGrpCd}
ORDER BY P.PTL_GRP_CD, P.PTL_CD

SELECT K.PTL_GRP_CD AS ptlGrpCd, K.PTL_CD AS ptlCd, K.PACKET_SEQ AS packetSeq, K.PACKET_TYPE AS packetType, K.DIRECTION AS direction, K.PACKET_EXPR AS packetExpr, K.RESPONSE_PTL_CD AS responsePtlCd, K.PARSE_RULE AS parseRule, K.DATA_COUNT AS dataCount, K.DATA_TYPE AS dataType, K.DATA_POSITION AS dataPosition FROM ju_protocol_packet K JOIN ju_protocol P ON P.PTL_GRP_CD = K.PTL_GRP_CD AND P.PTL_CD = K.PTL_CD AND P.USE_YN = 'YENO0001' WHERE K.USE_YN = 'YENO0001'
AND K.PTL_GRP_CD = #{ptlGrpCd}
ORDER BY K.PTL_GRP_CD, K.PTL_CD, K.PACKET_SEQ

SELECT DG.DEV_CD AS devCd, T.DAT_GR_CD AS datGrCd, T.DAT_CD AS datCd, T.DAT_IDX AS datIdx, T.DAT_TYPE AS datType, T.DAT_UNIT AS datUnit, T.TAG_ID AS tagId, TD.DAT_NM AS datNm, TD.DAT_MIN AS datMin, TD.DAT_MAX AS datMax, T.SORT_ORD AS sortOrd FROM ju_data_tag T JOIN ju_data_group DG ON DG.DAT_GR_CD = T.DAT_GR_CD AND DG.USE_YN = 'YENO0001' LEFT JOIN ju_data_tag_detail TD ON TD.DAT_GR_CD = T.DAT_GR_CD AND TD.DAT_CD = T.DAT_CD AND TD.DAT_IDX = T.DAT_IDX WHERE T.USE_YN = 'YENO0001'
AND DG.DEV_CD = #{devCd}
ORDER BY DG.DEV_CD, DG.SORT_ORD, T.DAT_GR_CD, T.SORT_ORD, T.DAT_CD, T.DAT_IDX

SELECT M.DEV_CD AS devCd, M.CHANNEL_KEY AS channelKey, M.PTL_CD AS ptlCd, M.DAT_GR_CD AS datGrCd, M.DAT_CD AS datCd, M.DAT_IDX AS datIdx, M.SCALE AS scale, M.OFFSET_VAL AS offsetVal, M.SORT_ORD AS sortOrd FROM ju_data_channel_map M JOIN ju_data_tag T ON T.DAT_GR_CD = M.DAT_GR_CD AND T.DAT_CD = M.DAT_CD AND T.DAT_IDX = M.DAT_IDX AND T.USE_YN = 'YENO0001' JOIN ju_data_group DG ON DG.DAT_GR_CD = T.DAT_GR_CD AND DG.USE_YN = 'YENO0001' WHERE M.USE_YN = 'YENO0001'
AND M.DEV_CD = #{devCd}
ORDER BY M.DEV_CD, M.SORT_ORD, M.CHANNEL_KEY, M.MAP_ID
